export const getGetDayActivityUrl = (params: GetDayActivityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/day-activity?${stringifiedParams}` : `/api/day-activity`
}

/**
 * @summary Get the planned activity for one person's day
 */
export const getDayActivity = async (params: GetDayActivityParams, options?: Parameters<typeof customFetch>[1]): Promise<DayActivity> => {

  return customFetch<DayActivity>(getGetDayActivityUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





